CREATE TABLE ezcontentobject_attribute (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, version INTEGER DEFAULT 0 NOT NULL, attribute_original_id INTEGER DEFAULT 0, contentclassattribute_id INTEGER DEFAULT 0 NOT NULL, contentobject_id INTEGER DEFAULT 0 NOT NULL, data_float DOUBLE PRECISION DEFAULT NULL, data_int INTEGER DEFAULT NULL, data_text CLOB DEFAULT NULL, data_type_string VARCHAR(50) DEFAULT '', language_code VARCHAR(20) DEFAULT '' NOT NULL, language_id BIGINT DEFAULT 0 NOT NULL, sort_key_int INTEGER DEFAULT 0 NOT NULL, sort_key_string VARCHAR(255) DEFAULT '' NOT NULL);
